mapper.select:
SELECT COUNT(*)
FROM sys_task
WHERE tenant_id = #{tenantId}
  AND handler_code = #{handlerCode}
  AND status IN ('RUNNING', 'CANCELLING')

SELECT id, tenant_id, task_type, task_name, handler_code, task_params, status, progress,
       total_count, processed_count, success_count, failed_count, result_data, error_message,
       creator_id, created_at,
       started_at, finished_at, expires_at
FROM sys_task
WHERE tenant_id = #{tenantId}
  AND creator_id = #{creatorId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id, tenant_id, task_type, task_name, handler_code, task_params, status, progress,
       total_count, processed_count, success_count, failed_count, result_data, error_message,
       creator_id, created_at,
       started_at, finished_at, expires_at
FROM sys_task
WHERE tenant_id = #{tenantId}
  AND creator_id = #{creatorId}
AND status = #{status}
AND task_type = #{type}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM sys_task
WHERE tenant_id = #{tenantId}
  AND creator_id = #{creatorId}
AND status = #{status}
AND task_type = #{type}

SELECT id, tenant_id, task_type, task_name, handler_code, task_params, status, progress,
       total_count, processed_count, success_count, failed_count, result_data, error_message,
       creator_id, created_at,
       started_at, finished_at, expires_at
FROM sys_task
WHERE status = 'PENDING'
  AND created_at < #{before}
AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}
